    check_version(&config.tsc_path, config.expected_versions)?;

    let mut command = Command::new(config.tsc_path.as_std_path());
    command.arg("--api").arg("--async").arg("--cwd").arg(config.cwd.as_std_path());
    command.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
    command.envs(config.extra_env.iter().map(|(k, v)| (k.as_str(), v.as_str())));
    // Best-effort fallback if `Supervisor::shutdown` is never called — this alone
    // doesn't guarantee reaping (Drop can't await), only `.shutdown()` does.
    command.kill_on_drop(true);

    let mut child = command
        .spawn()
        .map_err(|source| TscClientError::SpawnFailed { path: config.tsc_path.clone(), source: Arc::new(source) })?;

    let Some(stdin) = child.stdin.take() else { unreachable!("stdin is None despite Stdio::piped()") };
    let Some(stdout) = child.stdout.take() else { unreachable!("stdout is None despite Stdio::piped()") };
    let Some(stderr) = child.stderr.take() else { unreachable!("stderr is None despite Stdio::piped()") };

    spawn_stderr_drain(stderr);
    let (client, reader_handle) = Client::connect(stdin, stdout, config.max_frame_bytes);

    Ok((child, client, reader_handle))
}

/// Owns one `tsc --api` child process across its lifetime: spawn, version check,
/// crash-triggered restart (bounded, to avoid a restart storm), and shutdown/reaping.
pub struct Supervisor {
    child: Child,
    client: Client,
    reader_handle: tokio::task::JoinHandle<TscClientError>,
    config: SupervisorConfig,
    restart_attempts: Vec<Instant>,
    /// Set once a restart-storm cap is hit. Terminal — every later call short-circuits
    /// without touching the process again.
    failed: bool,
}

impl Supervisor {
    pub async fn spawn(config: SupervisorConfig) -> Result<Self, TscClientError> {
        let (child, client, reader_handle) = spawn_process(&config).await?;
        Ok(Self { child, client, reader_handle, config, restart_attempts: Vec::new(), failed: false })
    }

    /// The current session's low-level handle. Cheap to clone. After a
    /// supervisor-driven restart, `Client` clones obtained *before* the restart are
    /// permanently `SessionClosed` — call this again to get the live one.
    pub fn client(&self) -> Client {
        self.client.clone()
    }

    /// True while the current process's reader task is still running and the
    /// supervisor hasn't permanently failed. A crash between calls to this method and
    /// the next `request()` is still possible — this is a snapshot, not a guarantee.
    pub fn is_alive(&self) -> bool {
        !self.reader_handle.is_finished() && !self.failed
    }

    /// Sends a request through the current session. On `Crashed`, restarts once (if
    /// the restart budget allows) and retries the same call once before giving up —
    /// a request lost to a crash is never silently replayed more than that.
    pub async fn request(
        &mut self,
        method: &str,
        params: serde_json::Value,
        deadline: Duration,
    ) -> Result<TaggedResponse, TscClientError> {
        if self.failed {
            return Err(TscClientError::RestartStormDetected {
                attempts: self.restart_attempts.len() as u32,
                window: RESTART_WINDOW,
            });
        }

        match self.client.request(method, params.clone(), deadline).await {
            // A write failure to the child's stdin is, in practice, always the pipe
            // closing because the child exited — treated the same as a crash observed
            // through the read side, so a restart gets attempted either way.
            Err(TscClientError::Crashed { .. } | TscClientError::Write(_)) => {
                self.restart().await?;
                self.client.request(method, params, deadline).await
            }
            other => other,
        }
    }

    async fn restart(&mut self) -> Result<(), TscClientError> {
        let now = Instant::now();
        self.restart_attempts.retain(|attempt| now.duration_since(*attempt) < RESTART_WINDOW);

        if self.restart_attempts.len() as u32 >= MAX_RESTARTS {
            self.failed = true;
            return Err(TscClientError::RestartStormDetected {
                attempts: self.restart_attempts.len() as u32,
                window: RESTART_WINDOW,
            });
        }

        let backoff = BACKOFF_STEPS.get(self.restart_attempts.len()).copied().unwrap_or(BACKOFF_MAX);
        self.restart_attempts.push(now);
        tokio::time::sleep(backoff).await;

        // Best-effort cleanup of the crashed process before respawning — it may
        // already be gone, so failures here are expected and ignored.
        let _ = self.child.start_kill();
        let _ = self.child.wait().await;

        let (child, client, reader_handle) = spawn_process(&self.config).await?;
        self.child = child;
        self.client = client;
        self.reader_handle = reader_handle;
        Ok(())
    }

    /// Ends the session and guarantees the child is reaped, never left as a zombie:
    /// stop reading, race a grace period against a clean exit, force-kill past it,
    /// then unconditionally wait so the OS process table entry is always cleared.
    pub async fn shutdown(mut self) -> Result<(), TscClientError> {
        self.reader_handle.abort();
        drop(self.client);

        match tokio::time::timeout(SHUTDOWN_GRACE, self.child.wait()).await {
            Ok(Ok(_status)) => Ok(()),
            Ok(Err(source)) => Err(TscClientError::Reap(Arc::new(source))),
            Err(_elapsed) => {
                let _ = self.child.start_kill();
                let _ = self.child.wait().await; // unconditional — never left unreaped
                Ok(())
            }
        }
    }
}
use std::sync::Arc;
use std::time::Duration;

use camino::Utf8PathBuf;

/// One variant family per Lifecycle-gate item (docs/type-checker-integration.md,
/// "Gates before it ships") so a caller or test can tell failure modes apart.
///
/// `Clone` on purpose, not just for this crate's own internal fan-out (one session-
/// ending failure delivered to every pending caller — see `Client::fail_all_pending`):
/// a caller-facing error type that can't be cloned forces callers to choose between
/// logging it and propagating it. The only non-`Clone` sources are `io::Error` and
/// `serde_json::Error`, `Arc`-wrapped below so cloning the rare error path is just a
/// refcount bump, never a real cost on the common (success) path.
#[derive(Debug, Clone, thiserror::Error)]
#[non_exhaustive]
pub enum TscClientError {
    #[error("tsc binary not found at {path} — install `typescript@next` (npm i typescript@next) or pass an explicit path ({source})")]
    SpawnFailed {
        path: Utf8PathBuf,
        #[source]
        source: Arc<std::io::Error>,
    },

    #[error("tsc at {path} reports version {found:?}, not pinned (expected one of {expected:?})")]
    UnsupportedVersion { path: Utf8PathBuf, found: String, expected: &'static [&'static str] },

    #[error("could not determine tsc's version at {path}: {reason}")]
    VersionCheckFailed { path: Utf8PathBuf, reason: String },

    #[error("request {method:?} timed out after {after:?}")]
    Timeout { method: String, after: Duration },

    #[error("tsc exited unexpectedly (status: {status:?})")]
    Crashed { status: Option<std::process::ExitStatus> },

    #[error("tsc restarted {attempts} times within {window:?}; treating as permanently failed")]
    RestartStormDetected { attempts: u32, window: Duration },

    #[error("oversized frame: declared Content-Length {declared} exceeds the {cap}-byte cap")]
    OversizedFrame { declared: usize, cap: usize },

    #[error("malformed frame: {reason:?}")]
    MalformedFrame { reason: MalformedFrameReason },

    #[error("tsc returned a JSON-RPC error (code {code}): {message}")]
    RpcError { code: i64, message: String, data: Option<serde_json::Value> },

    #[error("session already shut down or permanently failed")]
    SessionClosed,

    #[error("I/O error writing to tsc: {0}")]
    Write(#[source] Arc<std::io::Error>),

    #[error("I/O error reading from tsc: {0}")]
    Read(#[source] Arc<std::io::Error>),

    #[error("failed to serialize a request: {0}")]
    Serialize(#[source] Arc<serde_json::Error>),

    #[error("failed to reap tsc's process: {0}")]
    Reap(#[source] Arc<std::io::Error>),
}

/// A malformed **header** desyncs the stream (the next frame's byte offset becomes
/// unknowable) and is always fatal for the session. A malformed **body** is scoped to
/// one frame — the declared length was valid, so the reader can resync on the next
/// frame — and the caller decides whether that's fatal for its use case.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum MalformedFrameReason {
    NoContentLengthHeader,
    UnparsableContentLength,
    TruncatedBody,
    InvalidJson,
}

/// Required by `tokio_util::codec::Decoder::Error`: `FramedRead` surfaces a read-side
/// I/O failure through the decoder's own error type.
impl From<std::io::Error> for TscClientError {
    fn from(source: std::io::Error) -> Self {
        Self::Read(Arc::new(source))
    }
}
//! Process supervisor and JSON-RPC transport client for TypeScript 7's `tsc --api`.
//!
//! Standalone: this crate has no dependency on `oxc-react-docgen-core` and nothing in
//! the workspace consumes it yet. It exists to satisfy the Lifecycle gate in
//! `docs/type-checker-integration.md` ("Gates before it ships") — missing binary,
//! unsupported version, timeout, crash, restart storm, malformed/oversized frame,
//! partial project failure, shutdown reaping, stale notification — before any of the
//! actual `typescript/unstable/*` checker methods get wired up to a merge step.
//!
//! This crate deliberately has no `crates/core`-style panic containment
//! (`panic_guard::contain_panic`): that exists to contain panics from caller-supplied
//! closures run on rayon/NAPI boundaries. Nothing here calls an arbitrary caller
//! closure — the only untrusted input is bytes from a child process, handled through
//! `Result`, never `.unwrap()`/`.expect()`.

mod client;
mod error;
mod protocol;
mod supervisor;
pub mod transport; // also used by tests/bin/fake_tsc.rs, so client and fake server can't drift on wire format

pub use client::{Client, TaggedResponse};
pub use error::{MalformedFrameReason, TscClientError};
pub use protocol::Notification;
pub use supervisor::{Supervisor, SupervisorConfig};
use serde::{Deserialize, Serialize};

/// A JSON-RPC request id. Newtype over `u64` so a raw index into another
/// collection can't be passed where a request id is expected.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct RequestId(pub u64);

#[derive(Debug, Clone, Serialize)]
pub struct RequestMessage {
    pub id: RequestId,
    pub method: String,
    pub params: serde_json::Value,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ResponseMessage {
    pub id: RequestId,
    #[serde(default)]
    pub result: Option<serde_json::Value>,
    #[serde(default)]
    pub error: Option<RpcErrorObject>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct RpcErrorObject {
    pub code: i64,
    pub message: String,
    #[serde(default)]
    pub data: Option<serde_json::Value>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct NotificationMessage {
    pub method: String,
    #[serde(default)]
    pub params: serde_json::Value,
}

/// A notification surfaced to a caller via [`crate::Client::take_notifications`].
#[derive(Debug, Clone)]
pub struct Notification {
    pub method: String,
    pub params: serde_json::Value,
}

#[derive(Debug)]
pub enum IncomingMessage {
    Response(ResponseMessage),
    Notification(NotificationMessage),
}

/// Dispatches a decoded frame body by shape: an `id` alongside `result`/`error` is a
/// response to one of our requests; anything else with a `method` is a notification.
/// tsc --api never sends us a request of its own (no server-initiated calls in this
/// protocol), so those are the only two shapes handled.
pub fn parse_incoming(body: &[u8]) -> Result<IncomingMessage, serde_json::Error> {
    let value: serde_json::Value = serde_json::from_slice(body)?;
    let is_response = value.get("id").is_some() && (value.get("result").is_some() || value.get("error").is_some());
    if is_response {
        Ok(IncomingMessage::Response(serde_json::from_value(value)?))
    } else {
        Ok(IncomingMessage::Notification(serde_json::from_value(value)?))
    }
}

//! A scenario-driven fake `tsc --api` process for the Lifecycle-gate test suite.
//! Scenario is picked via the `FAKE_TSC_SCENARIO` env var (env, not argv, matching
//! `crates/cli/src/config.rs`'s precedent for test/caller-controlled input):
//! `echo` (default), `never_respond`, `hang_after_n:<N>`, `exit_after:<N>:<code>`,
//! `crash_immediately:<code>`, `garbage_bytes`, `bad_content_length`,
//! `oversized_frame:<N>`, `truncated_body`, `reorder_ack`, `shutdown_slow:<ms>`.
//!
//! Valid-frame scenarios are built on this crate's own `transport::{ContentLengthDecoder,
//! write_frame}`, so this fixture can't drift from what the real client parses;
//! bad-frame scenarios intentionally hand-write raw bytes instead.

use std::time::Duration;

use oxc_react_docgen_tsc_client::transport::{write_frame, ContentLengthDecoder, DEFAULT_MAX_FRAME_BYTES};
use tokio::io::AsyncWriteExt;
use tokio_stream::StreamExt;
use tokio_util::codec::FramedRead;

type Requests = FramedRead<tokio::io::Stdin, ContentLengthDecoder>;

fn requests() -> Requests {
    FramedRead::new(tokio::io::stdin(), ContentLengthDecoder::new(DEFAULT_MAX_FRAME_BYTES))
}

#[tokio::main]
async fn main() {
    let scenario = std::env::var("FAKE_TSC_SCENARIO").unwrap_or_else(|_| "echo".to_string());
    let mut parts = scenario.splitn(3, ':');
    let name = parts.next().unwrap_or("echo");
    let arg1 = parts.next();
    let arg2 = parts.next();

    match name {
        "never_respond" => never_respond().await,
        "hang_after_n" => hang_after_n(arg1.and_then(|s| s.parse().ok()).unwrap_or(0)).await,
        "exit_after" => {
            exit_after(arg1.and_then(|s| s.parse().ok()).unwrap_or(0), arg2.and_then(|s| s.parse().ok()).unwrap_or(1))
                .await;
        }
        "crash_immediately" => std::process::exit(arg1.and_then(|s| s.parse().ok()).unwrap_or(1)),
        "garbage_bytes" => garbage_bytes().await,
        "bad_content_length" => bad_content_length().await,
        "oversized_frame" => oversized_frame(arg1.and_then(|s| s.parse().ok()).unwrap_or(usize::MAX)).await,
        "truncated_body" => truncated_body().await,
        "reorder_ack" => reorder_ack().await,
        "shutdown_slow" => shutdown_slow(arg1.and_then(|s| s.parse().ok()).unwrap_or(10_000)).await,
        _ => echo().await,
    }
}

fn request_id(request: &serde_json::Value) -> serde_json::Value {
    request.get("id").cloned().unwrap_or(serde_json::Value::Null)
}

async fn read_request(reader: &mut Requests) -> Option<serde_json::Value> {
    match reader.next().await {
        Some(Ok(body)) => serde_json::from_slice(&body).ok(),
        _ => None,
    }
}

async fn respond<W: tokio::io::AsyncWrite + Unpin>(writer: &mut W, id: &serde_json::Value, result: serde_json::Value) {
    let body = serde_json::json!({ "id": id, "result": result });
    if let Ok(bytes) = serde_json::to_vec(&body) {
        let _ = write_frame(writer, &bytes).await;
    }
}

async fn respond_error<W: tokio::io::AsyncWrite + Unpin>(
    writer: &mut W,
    id: &serde_json::Value,
    code: i64,
    message: &str,
) {
    let body = serde_json::json!({ "id": id, "error": { "code": code, "message": message } });
    if let Ok(bytes) = serde_json::to_vec(&body) {
        let _ = write_frame(writer, &bytes).await;
    }
}

/// Baseline: echoes `params` back as `result.echo`, or replies with an `error` object
/// when `params.fail` is `true` — used to test that one failing call doesn't affect a
/// concurrently in-flight sibling (partial project failure).
async fn echo() {
    let mut reader = requests();
    let mut stdout = tokio::io::stdout();
    while let Some(request) = read_request(&mut reader).await {
        let id = request_id(&request);
        let params = request.get("params").cloned().unwrap_or(serde_json::Value::Null);
        if params.get("fail").and_then(serde_json::Value::as_bool).unwrap_or(false) {
            respond_error(&mut stdout, &id, -32000, "requested failure").await;
        } else {
            respond(&mut stdout, &id, serde_json::json!({ "echo": params })).await;
        }
    }
}

/// Reads and discards requests forever, never responding — exercises the client's
/// per-request timeout.
async fn never_respond() {
    let mut reader = requests();
    while read_request(&mut reader).await.is_some() {}
}

/// Responds normally to the first `n` requests, then keeps reading (so the pipe never
/// backs up) without ever responding again.
async fn hang_after_n(n: usize) {
    let mut reader = requests();
    let mut stdout = tokio::io::stdout();
    let mut count = 0usize;
    while let Some(request) = read_request(&mut reader).await {
        count += 1;
        if count > n {
            continue;
        }
        respond(&mut stdout, &request_id(&request), serde_json::json!({ "ok": true })).await;
    }
}

/// Responds normally to the first `n` requests, then exits with `code` — exercises
/// crash detection mid-session (a request issued after the `n`th gets no response).
async fn exit_after(n: usize, code: i32) {
    let mut reader = requests();
    let mut stdout = tokio::io::stdout();
    let mut count = 0usize;
    while let Some(request) = read_request(&mut reader).await {
        count += 1;
        respond(&mut stdout, &request_id(&request), serde_json::json!({ "ok": true })).await;
        if count >= n {
            std::process::exit(code);
        }
    }
}

async fn garbage_bytes() {
    // Ends with the blank-line header terminator so the reader reaches "a header block
    // was read, but it has no Content-Length" rather than hitting EOF mid-header.
    let mut stdout = tokio::io::stdout();
    let _ = stdout.write_all(b"this is not a Content-Length frame at all\r\n\r\n").await;
    let _ = stdout.flush().await;
    tokio::time::sleep(Duration::from_millis(300)).await;
}

async fn bad_content_length() {
    let mut stdout = tokio::io::stdout();
    let _ = stdout.write_all(b"Content-Length: not-a-number\r\n\r\n").await;
    let _ = stdout.flush().await;
    tokio::time::sleep(Duration::from_millis(300)).await;
}

/// Declares a `Content-Length` far larger than the client's cap and never writes that
/// many bytes — the client must reject based on the declared length alone.
async fn oversized_frame(declared: usize) {
    let mut stdout = tokio::io::stdout();
    let header = format!("Content-Length: {declared}\r\n\r\n");
    let _ = stdout.write_all(header.as_bytes()).await;
    let _ = stdout.flush().await;
    tokio::time::sleep(Duration::from_millis(300)).await;
}

async fn truncated_body() {
    let mut stdout = tokio::io::stdout();
    let _ = stdout.write_all(b"Content-Length: 100\r\n\r\ntoo short").await;
    let _ = stdout.flush().await;
    tokio::time::sleep(Duration::from_millis(300)).await;
}

/// Reads two requests, answers the second one first — proves a response's `seq`
/// reflects wire-arrival order, not issue order (the stale-notification mechanism).
async fn reorder_ack() {
    let mut reader = requests();
    let mut stdout = tokio::io::stdout();
    let Some(first) = read_request(&mut reader).await else { return };
    let Some(second) = read_request(&mut reader).await else { return };
    respond(&mut stdout, &request_id(&second), serde_json::json!({ "order": "second" })).await;
    respond(&mut stdout, &request_id(&first), serde_json::json!({ "order": "first" })).await;
    while let Some(request) = read_request(&mut reader).await {
        respond(&mut stdout, &request_id(&request), serde_json::json!({ "ok": true })).await;
    }
}

/// Answers requests normally but ignores shutdown for `delay_ms` before exiting —
/// forces the supervisor's shutdown grace period to elapse into a force-kill.
async fn shutdown_slow(delay_ms: u64) {
    let mut reader = requests();
    let mut stdout = tokio::io::stdout();
    let deadline = tokio::time::Instant::now() + Duration::from_millis(delay_ms);
    loop {
        let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
        if remaining.is_zero() {
            break;
        }
        tokio::select! {
            request = read_request(&mut reader) => {
                let Some(request) = request else { break };
                respond(&mut stdout, &request_id(&request), serde_json::json!({ "ok": true })).await;
            }
            () = tokio::time::sleep(remaining) => break,
        }
    }
}
//! Shared helper for the Lifecycle-gate integration tests: builds a `SupervisorConfig`
//! pointing at a fresh copy of the `fake-tsc` binary inside a `node_modules/typescript/
//! bin/` layout, so `check_version`'s `package.json` lookup finds a real, matching
//! version rather than needing every test to fake that out itself.
//!
//! Each `tests/*.rs` file compiles this module separately as its own crate, so a
//! helper unused by one particular test binary is expected, not a real dead-code
//! finding — hence the blanket allow below.
#![allow(dead_code)]

use camino::Utf8PathBuf;
use oxc_react_docgen_tsc_client::SupervisorConfig;

pub const PINNED_VERSION: &str = "7.1.0-test";

/// Returns the temp dir (kept alive for the caller's test duration) and a config ready
/// to `Supervisor::spawn`, with `FAKE_TSC_SCENARIO` set to `scenario`.
pub fn spawn_fake(scenario: &str) -> (tempfile::TempDir, SupervisorConfig) {
    let dir = tempfile::tempdir().expect("create temp dir for fake-tsc layout");
    let (tsc_path, cwd) = layout_with_version(&dir, PINNED_VERSION);
    let mut config = SupervisorConfig::new(tsc_path, cwd, &[PINNED_VERSION]);
    config.extra_env.push(("FAKE_TSC_SCENARIO".to_string(), scenario.to_string()));
    (dir, config)
}

/// Builds the `node_modules/typescript/{package.json,bin/tsc}` layout with the given
/// version string and a copy of the real `fake-tsc` binary at `bin/tsc`. Returns
/// `(tsc_path, cwd)`.
pub fn layout_with_version(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
    let typescript_dir = dir.path().join("node_modules").join("typescript");
    let bin_dir = typescript_dir.join("bin");
    std::fs::create_dir_all(&bin_dir).expect("create node_modules/typescript/bin");
    std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
        .expect("write package.json");

    let fake_tsc_src = std::path::PathBuf::from(env!("CARGO_BIN_EXE_fake-tsc"));
    let tsc_dest = bin_dir.join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
    std::fs::copy(&fake_tsc_src, &tsc_dest).expect("copy fake-tsc binary into place");

    (
        Utf8PathBuf::from_path_buf(tsc_dest).expect("temp path is UTF-8"),
        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
    )
}

/// Same layout, but without ever placing a binary at `bin/tsc` — for the missing-binary
/// case.
pub fn layout_without_binary(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
    let typescript_dir = dir.path().join("node_modules").join("typescript");
    std::fs::create_dir_all(&typescript_dir).expect("create node_modules/typescript");
    std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
        .expect("write package.json");
    let tsc_path = typescript_dir.join("bin").join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
    (
        Utf8PathBuf::from_path_buf(tsc_path).expect("temp path is UTF-8"),
        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
    )
}
mod common;

use std::time::Duration;

use oxc_react_docgen_tsc_client::{Client, TscClientError};

#[tokio::test]
async fn a_process_that_exits_mid_session_fails_the_next_request_as_crashed() {
    // Answers the first request, then exits — a second request gets no response.
    let (_dir, config) = common::spawn_fake("exit_after:1:7");
    let mut supervisor = oxc_react_docgen_tsc_client::Supervisor::spawn(config).await.expect("spawn fake tsc");

    let first = supervisor.request("first", serde_json::json!({}), Duration::from_secs(2)).await;
    assert!(first.is_ok(), "expected the first request to succeed, got {first:?}");

    // The second request may report Crashed directly, or (since Supervisor::request
    // auto-restarts once on Crashed) succeed against the restarted process — both are
    // correct; what matters is it isn't left hanging or silently wrong. Use the
    // low-level Client directly instead, which never restarts, to observe the crash
    // itself deterministically.
    let raw_client: Client = supervisor.client();
    // Give the crashed process's reader task a moment to notice EOF.
    tokio::time::sleep(Duration::from_millis(100)).await;
    let second = raw_client.request("second", serde_json::json!({}), Duration::from_secs(2)).await;
    match second {
        // Whether the crash surfaces as `Crashed` (reader task noticed EOF first) or
        // `Write` (the stdin pipe was already closed) is a timing race, not something
        // this crate controls — both mean the same thing: the process is gone.
        Err(TscClientError::Crashed { .. } | TscClientError::Write(_)) => {}
        Err(other) => panic!("expected Crashed or Write, got {other:?}"),
        Ok(response) => panic!("expected an error, got a response: {response:?}"),
    }
}
